<script lang="ts">import { tick } from 'svelte';import { ansiToHtml } from '../../lib/ansi';import { prefs } from '../../lib/state/prefs.svelte';import { LogBuffer, type BufferedLine } from '../../lib/state/logs.svelte';let { buffer, follow = $bindable(true) }: { buffer: LogBuffer; follow?: boolean } = $props();let el: HTMLDivElement;let newCount = $state(0);let filter = $state('');let level = $state('all');export function append(l: BufferedLine) { const atBottom = el ? el.scrollHeight - el.scrollTop - el.clientHeight < 40 : true; buffer.append(l); if (!atBottom) newCount++; if (follow && atBottom) { void tick().then(() => { if (el) el.scrollTop = el.scrollHeight; }); } }export function getBuffer() { return buffer; }let visible = $derived.by(() => { return buffer.ids.map((_, i) => buffer.at(i)).filter((l) => { if (filter && !l.text.toLowerCase().includes(filter.toLowerCase())) return false; if (level !== 'all' && l.level !== level) return false; return true; }).slice(-2000); });function jump() { follow = true; newCount = 0; if (el) el.scrollTop = el.scrollHeight; }function onScroll() { if (!el) return; const atBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 40; if (!atBottom) follow = false; else { follow = true; newCount = 0; } }</script><div class="toolbar"><input placeholder="Filter…" bind:value={filter} aria-label="Filter logs" /><select bind:value={level} aria-label="Level"><option value="all">all levels</option><option value="debug">debug</option><option value="info">info</option><option value="warn">warn</option><option value="error">error</option></select><label><input type="checkbox" bind:checked={prefs.data.wrap} /> wrap</label>{#if !follow}<button onclick={jump}>Jump to live · {newCount} new</button>{/if}</div><div class="log" bind:this={el} onscroll={onScroll} role="log" aria-live="off" class:wrap={prefs.data.wrap}>{#each visible as l}<div class="row"><span class="ts">{prefs.data.timestamps === 'off' ? '' : new Date(l.ts).toLocaleTimeString()}</span><span class="proc">{l.proc.slice(0, 8)}</span><span class="msg">{@html prefs.data.ansi ? ansiToHtml(l.text) : l.text}</span></div>{/each}</div><style>.toolbar{display:flex;gap:var(--space-3);padding:var(--space-3);border-bottom:1px solid var(--border)}.log{height:400px;overflow:auto;font-family:var(--font-mono);font-size:12px;background:var(--bg-0)}.row{display:flex;gap:var(--space-3);padding:0 var(--space-3);white-space:pre}.wrap .row{white-space:pre-wrap;word-break:break-all}.ts{color:var(--text-2)}.proc{color:var(--info)}</style>
